<script setup>
import { ref } from 'vue'; import { api } from '../services/api'; import { useRouter } from 'vue-router'; const router=useRouter()
const username=ref(''),password=ref(''),message=ref(''),user=ref(null),token=ref(''),current=ref(''),next=ref(''),confirm=ref('')
async function login(){try{const r=await api.post('/admin/login',{username:username.value,password:password.value});user.value=r.data.user;token.value=r.data.token;sessionStorage.setItem('gallery_token',token.value);if(!user.value.must_change_password){router.push('/admin/dashboard');return}message.value=user.value.must_change_password?'Anda wajib mengganti password sebelum melanjutkan.':'Login berhasil.'}catch{message.value='Login gagal. Periksa username dan password.'}}
async function change(){try{await api.post('/admin/change-password',{current_password:current.value,password:next.value,password_confirmation:confirm.value},{headers:{Authorization:'Bearer '+token.value}});message.value='Password berhasil diganti.';user.value.must_change_password=false;router.push('/admin/dashboard')}catch(e){message.value=e.response?.data?.message||'Password tidak dapat diganti.'}}
</script>
<template><main class="login"><div class="login-box"><div class="eyebrow"><i></i> AREA ADMINISTRATOR</div><h1>Masuk admin</h1><p>Masuk untuk mengelola dokumentasi Jakarta.</p><p v-if="message" class="notice">{{message}}</p><form v-if="!user" @submit.prevent="login"><label>Username<input v-model="username" required autocomplete="username"></label><label>Password<input v-model="password" type="password" required autocomplete="current-password"></label><button class="button dark">Masuk →</button></form><form v-else-if="user.must_change_password" @submit.prevent="change"><label>Password saat ini<input v-model="current" type="password" required></label><label>Password baru (minimal 12 karakter)<input v-model="next" type="password" minlength="12" required></label><label>Konfirmasi password<input v-model="confirm" type="password" required></label><button class="button dark">Simpan password →</button></form></div></main></template>


